# area: narrowing_builtin
# hypothesis: ty keeps the narrowing of an aliased condition (is_none = x is None) after x is reassigned to None at the end of a loop body, so the next iteration types x as int; mypy and pyright should report the None operand.
from typing import reveal_type


def f(x: int | None) -> int:
    is_none = x is None
    total = 0
    for _ in range(2):
        if not is_none:
            total += x + 1  # expect-error
        x = None
    return total


def g(x: int | None) -> int:
    is_none = x is None
    total = 0
    i = 0
    while i < 2:
        if not is_none:
            total += x + 1  # expect-error
        x = None
        i += 1
    return total


def h(x: int | None) -> int:
    total = 0
    for _ in range(2):
        is_none = x is None
        if not is_none:
            total += x + 1
        x = None
    return total


reveal_type(h(3))
try:
    print(f(3))
except TypeError as exc:
    print('TypeError:', exc)
try:
    print(g(3))
except TypeError as exc:
    print('TypeError:', exc)
print(h(3))
